INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('check_1', 'Rule 18 Exemption Pre-Check', 'Checks if the product is exempt under Rule 18 (institutional/industrial use, net qty <= 10g/10ml, agricultural produce > 50kg, or export-only).', 'exemption', 'CRITICAL', 'Ensure statutory exemption eligibility criteria (net qty ≤ 10g/ml, agricultural produce > 50kg, or industrial/export use) are clearly documented on packaging.', '{"max_qty_exempt_g_ml": 10.0, "max_agricultural_produce_kg": 50.0}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('check_2', 'Rule 6(1)(a)', 'Every package must bear the name and complete address of the manufacturer, packer, or importer.', 'presence', 'CRITICAL', 'Include the full legal name and complete postal address of the manufacturer/packer with a valid 6-digit PIN code.', '{"required_fields": ["manufacturer_name", "manufacturer_address"]}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('check_3', 'Rule 6(1)(b)', 'The common or generic name of the commodity contained in the package must be declared.', 'presence', 'MAJOR', 'Declare the common or generic name of the packaged commodity prominently on the Principal Display Panel.', '{"required_fields": ["generic_name"]}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('check_5', 'Rule 6(1)(d)', 'The month and year in which the commodity is manufactured or pre-packed or imported must be declared.', 'regex', 'MAJOR', 'Declare the month and year of manufacturing or pre-packing in standard format (e.g. ''08/2026'' or ''Aug 2026'').', '{"regex_pattern": "(?i)\\b(?:0[1-9]|1[0-2])[/\\-\\.](?:19|20)?\\d{2}\\b|\\b(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\\s+(?:19|20)?\\d{2}\\b"}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('check_6', 'Rule 6(1)(e)', 'The Maximum Retail Price (MRP) must be declared clearly, including the phrase ''inclusive of all taxes'' or ''incl. of all taxes''.', 'regex', 'CRITICAL', 'Add the mandatory statutory suffix ''inclusive of all taxes'' or ''incl. of all taxes'' immediately adjacent to the MRP declaration.', '{"required_phrases": ["inclusive of all taxes", "incl. of all taxes", "incl.of all taxes", "incl of all taxes"], "regex_pattern": "(?i)\\b(?:m\\.?r\\.?p\\.?|max\\.?(?:imum)?\\s*retail\\s*price)\\s*(?:rs\\.?|\u20b9)?\\s*\\d+(?:\\.\\d{2})?"}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('check_7', 'Rule 6(1)(g)', 'Every package must bear the name, address, telephone number, and email address of the consumer care contact.', 'presence', 'MAJOR', 'Declare complete consumer care contact details including contact officer/cell name, postal address, working phone number, and valid email ID.', '{"required_fields": ["consumer_care_name", "consumer_care_phone", "consumer_care_email", "consumer_care_address"]}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('check_8', 'Rule 6(1)(f)', 'For imported commodities and general goods, the country of origin must be declared.', 'presence', 'MAJOR', 'Declare the Country of Origin clearly on the packaging (e.g., ''Country of Origin: India'' or ''Made in India'').', '{"required_fields": ["country_of_origin"]}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('check_9', 'Rule 6(1)(a) Importer', 'For imported commodities, the name and address of the importer must be declared.', 'presence', 'CRITICAL', 'For imported commodities, declare the registered company name and complete postal address of the Indian importer.', '{"required_fields": ["importer_name", "importer_address"]}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('check_12', 'Rule 23 E-Commerce', 'For e-commerce sales, digital listing declarations must display all mandatory statutory fields.', 'presence', 'MAJOR', 'Ensure the digital marketplace listing displays all mandatory statutory declarations (MRP, Net Quantity, Country of Origin, Manufacturer details, Consumer care) matching physical label.', '{"fields_to_compare": ["mrp", "net_quantity", "manufacturer_name", "country_of_origin"]}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('check_4', 'Rule 6(1)(c)', 'The net quantity, in terms of standard unit of weight, measure or number, must be declared.', 'measurement', 'CRITICAL', 'Declare net quantity using statutory metric unit symbols (''g'', ''kg'', ''ml'', ''l'', ''pcs'', ''N'') without non-standard abbreviations like ''gms'' or ''ltrs''.', '{"allowed_units": ["g", "grm", "gram", "grams", "kg", "kg.", "kilogram", "kilograms", "ml", "ml.", "milliliter", "milliliters", "l", "l.", "liter", "liters", "litre", "litres", "m", "meter", "meters", "pcs", "units", "u", "n", "pair", "pairs", "piece", "pieces"]}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('check_10', 'Rule 6(3) / Font Height', 'Minimum font height of declarations must conform to the Principal Display Panel (PDP) area regulations.', 'measurement', 'MINOR', 'Increase letter and numeral font height to meet the minimum statutory height (e.g. min 2.0 mm for PDP area > 100 cm²) based on package surface area.', '{"pdp_font_rules": [{"max_area_cm2": 50, "min_height_mm": 1.0}, {"max_area_cm2": 100, "min_height_mm": 1.5}, {"max_area_cm2": 500, "min_height_mm": 2.0}, {"max_area_cm2": 1000, "min_height_mm": 3.0}, {"max_area_cm2": 999999, "min_height_mm": 4.0}]}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('check_11', 'Rule 8 / Standard Sizes', 'Pre-packaged commodity net quantity must conform to the prescribed standard sizes for defined categories.', 'measurement', 'MAJOR', 'Pack the commodity in one of the prescribed standard net quantity sizes specified under the Second Schedule of Legal Metrology Rules.', '{"standard_sizes": {"tea": [25, 50, 75, 100, 125, 150, 200, 250, 500, 1000], "biscuits": [25, 50, 75, 100, 150, 200, 250, 300, 400], "edible_oil": [50, 100, 200, 250, 500, 1000, 2000, 3000, 5000], "soap": [25, 50, 75, 100, 125, 150], "water": [100, 150, 200, 250, 300, 500, 750, 1000, 1500, 2000, 5000]}}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('fssai_check_1', 'FSSAI Sec 31 / License 3-Tier', 'Every food package must display a valid 14-digit FSSAI License/Registration number verified through mathematical syntax, FoSCoS portal, and state registry cache.', 'presence', 'CRITICAL', 'Obtain and declare a valid 14-digit FSSAI license/registration number with the official FSSAI logo on the Principal Display Panel.', '{"syntax_pattern": "^[12][0-3][0-9]\\d{11}$"}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('fssai_check_2', 'FSSAI 2020 Reg 5(3) / Nutrition', 'Nutritional Information per 100g/100ml and per serving declaring Energy, Protein, Carbohydrates, Total/Added Sugars, Fat, Saturated/Trans Fat, and Sodium with mathematical consistency.', 'measurement', 'CRITICAL', 'Include a structured Nutritional Information table declaring all 8 mandatory nutrients per 100g/100ml and per serving.', '{"mandatory_nutrients": ["energy", "protein", "carbohydrates", "total_fat", "saturated_fat", "trans_fat", "sodium"]}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('fssai_check_3', 'FSSAI 2020 Reg 5(4) / Veg Logo', 'Mandatory Vegetarian (green circle in green square) or Non-Vegetarian (brown triangle in brown square) logo conforming to PDP surface area millimeter dimensions.', 'measurement', 'MAJOR', 'Display the compliant Veg (green circle in green square) or Non-Veg (brown triangle in brown square) symbol meeting minimum PDP millimeter dimensions.', '{"pdp_sizing_mm": {"<=100": 6.0, "<=500": 8.0, "<=2500": 10.0, ">2500": 16.0}}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('fssai_check_4', 'FSSAI 2020 Reg 5(1) / Ingredients', 'List of Ingredients in strictly descending order of weight or volume at manufacture with Quantitative Ingredient Declaration (QUID) monotonicity.', 'presence', 'MAJOR', 'List all ingredients in strictly descending order of incoming weight/volume, ensuring declared percentages descend monotonically.', '{"descending_order_enforced": true}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('fssai_check_5', 'FSSAI 2020 Reg 5(2) / Allergens', 'Mandatory separate allergen declaration (''Contains: ...'') for 8 statutory allergen classes (gluten, crustaceans, milk, eggs, fish, nuts, soy, sulphites).', 'presence', 'CRITICAL', 'Add a separate allergen advisory statement immediately adjacent to ingredients (e.g. ''Contains: Wheat (Gluten), Milk, Tree Nuts'').', '{"allergen_classes": ["gluten", "crustaceans", "milk", "eggs", "fish", "nuts", "soy", "sulphites"]}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('fssai_check_6', 'FSSAI 2020 Reg 5(10) / Expiry Date', 'Mandatory Expiry Date or Use By date declaration. ''Best Before'' date is optional and cannot substitute for an explicit Expiry Date.', 'regex', 'CRITICAL', 'Declare an explicit ''Expiry Date'' or ''Use By'' date on the package (e.g. ''Expiry: 31/12/2026''). ''Best Before'' is not a legal substitute.', '{"mandatory_keywords": ["expiry", "use by", "exp"]}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('apparel_check_1', 'Textile Rule / Fiber 100% Math', 'Mandatory declaration of fiber/fabric names with exact percentage values mathematically totaling 100%.', 'measurement', 'CRITICAL', 'Declare all component fibers and fabrics with percentage values that sum exactly to 100% (e.g. ''60% Cotton, 40% Polyester'').', '{"exact_sum": 100.0}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('apparel_check_2', 'Rule 6(1)(c) / Size & Metric', 'Garment size must declare physical metric dimensions in centimeters (cm) or meters (m); international letter size (S/M/L/XL) alone is legally insufficient.', 'measurement', 'CRITICAL', 'Pair international letter sizes (S/M/L/XL) with physical metric measurements in centimeters (e.g. ''Size: L (Chest 102 cm, Length 76 cm)'').', '{"metric_pairing_required": true}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('apparel_check_3', 'Rule 6(1)(e) / MRP & Tax Suffix', 'Maximum Retail Price in INR/Rupees explicitly accompanied by mandatory ''inclusive of all taxes'' suffix with OCR typo tolerance.', 'regex', 'CRITICAL', 'Include the mandatory statutory suffix ''inclusive of all taxes'' or ''incl. of all taxes'' immediately adjacent to the MRP declaration.', '{"required_phrases": ["inclusive of all taxes", "incl. of all taxes"]}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('apparel_check_4', 'Rule 6(1)(b) / Apparel Taxonomy', 'Common or generic apparel commodity name must match recognized national Department of Consumer Affairs taxonomy (>=80% similarity).', 'presence', 'MAJOR', 'Declare the statutory generic apparel commodity name (e.g. ''Men''s T-Shirt'', ''Formal Trousers'', ''Cotton Saree'') separate from brand name.', '{"taxonomy_threshold": 80}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('apparel_check_5', 'Rule 6(1)(f) / Consumer Care 3-Way', 'All 3 mandatory consumer care channels must be present: working telephone helpline, valid email, and physical postal address with 6-digit PIN code.', 'presence', 'CRITICAL', 'Provide all 3 statutory consumer care channels: working telephone number (or 1800 toll-free), valid email ID, and postal address with 6-digit PIN code.', '{"required_channels": ["phone", "email", "address"]}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('apparel_check_6', 'Rule 6(1)(d) / Contextual MFD', 'Month and year of manufacture or pre-packing declared in explicit statutory context (MFD / MFG / PKD / Packed).', 'regex', 'MAJOR', 'Declare the manufacturing or packing date in explicit statutory context (e.g. ''MFD: 08/2026'' or ''PKD: Aug 2026'').', '{"context_keywords": ["mfd", "mfg", "pkd", "packed", "manufactured"]}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
INSERT INTO rule_definitions (rule_id, rule_citation, description, check_type, severity, fix_suggestion, validation_logic) VALUES ('apparel_check_7', 'Rule 6(1)(f) / Country of Origin', 'Explicit Country of Origin declaration (''Country of Origin: ...'' or ''Made in ...'') separate from general manufacturer address mentions.', 'presence', 'CRITICAL', 'Include an explicit Country of Origin declaration (e.g. ''Country of Origin: India'' or ''Made in India'') on the garment label.', '{"explicit_context_required": true}'::jsonb) ON CONFLICT (rule_id) DO UPDATE SET rule_citation = EXCLUDED.rule_citation, description = EXCLUDED.description, severity = EXCLUDED.severity, fix_suggestion = EXCLUDED.fix_suggestion, validation_logic = EXCLUDED.validation_logic;
